-- Generated by scripts/export_jana_demo.py from knowledge_base/demo/articles.json.
-- DEMO DATA ONLY, not approved Jana Post HR policy.
-- LOCAL TEST DATABASE ONLY: apply after database/migration-plan.json.
-- Reuses the first three demo IDs; other articles are not deleted.
begin;
set local standard_conforming_strings = on;
do $$ begin if current_database() not like 'posttech_test_%' then raise exception 'Local test database required'; end if; end $$;
insert into public.knowledge_articles
    (id, title, content, source_title, source_url, keywords, active, version, editorial_state)
values
('20000000-0000-4000-8000-000000000001', 'Как оформить отпуск', 'В объединённом демо-прототипе отпуск оформляется в разделе «Заявки»: выберите «Отпуск», задайте дату начала и окончания и отправьте заявку. Дата начала не должна быть в прошлом, дата окончания не должна предшествовать началу. Пересечения с ожидающими и одобренными отпусками отклоняются. Последний день включается в отпуск; дни считаются календарными. После отправки дни резервируются. Заявку сначала рассматривает назначенный руководитель или директор, затем HR; после первого согласования статус pending_hr, после окончательного — approved. Если руководитель не назначен, заявку рассматривает HR напрямую. При окончательном одобрении дни списываются из кадрового остатка один раз, а резерв снимается. Автоматическое оформление документов в 1С или Documentolog не подтверждено.', 'Демо: оформление заявки на отпуск', null, array['отпуск', 'отпуска', 'заявка', 'заявку', 'оформить', 'даты']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000002', 'Как запросить аванс', 'Для аванса откройте «Заявки», выберите «Аванс», укажите положительную сумму и отправьте заявку; даты отпуска не нужны. Заявка проходит согласование назначенным руководителем или директором и окончательную проверку HR; без назначенного руководителя её рассматривает HR. Одобрение аванса фиксирует решение в приложении, но не выполняет банковский перевод. Валюта, сроки выплаты и допустимая доля зарплаты в этой демонстрационной базе не установлены — уточните их у HR.', 'Демо: оформление заявки на аванс', null, array['аванс', 'аванса', 'запросить', 'сумма', 'заявка']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000003', 'Кто видит кадровые данные', 'Сотрудник видит свой профиль и свои заявки. Руководитель и директор видят профили прямых подчинённых и заявки, назначенные им на согласование или ранее рассмотренные ими. Смена руководителя не открывает новому начальнику старые заявки автоматически. HR имеет доступ к профилям и заявкам и назначает роли через административный раздел в пределах серверных разрешений. Временный заместитель получает только предусмотренные делегированием права на согласование, а не полный доступ к чужим данным. Личные уведомления доступны только их получателю, в том числе для HR. Роль определяется сервером, текст сообщения Jana не изменяет права доступа.', 'Демо: роли и доступ к данным', null, array['доступ', 'роль', 'роли', 'данные', 'кадровые', 'руководитель', 'видит']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000004', 'Где посмотреть статус заявки', 'Статус заявки отображается в разделе «Заявки» и её карточке. pending означает ожидание первого решения; pending_hr — ожидание окончательного решения HR; approved — одобрено; rejected — отклонено; cancelled — отменено. В карточке доступны история и оставленный проверяющим комментарий. При отказе причина обязательна. Сотрудник может отменить свою заявку на этапах pending и pending_hr. Одобренную заявку этим действием отменить нельзя. Jana не читает текущую личную заявку; откройте карточку самостоятельно.', 'Демо: статусы заявок', null, array['статус', 'статусы', 'заявки', 'посмотреть', 'pending', 'approved', 'rejected', 'cancelled']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000005', 'Где посмотреть остаток отпуска', 'В разделе баланса отпуска показаны кадровый остаток, резервы и доступные дни. Новая заявка резервирует включительно все календарные дни периода; ожидание HR сохраняет резерв. При окончательном одобрении HR кадровый остаток уменьшается один раз, а соответствующий резерв закрывается: двойного вычета нет. Отказ или отмена ожидающей заявки освобождает резерв. Старые одобренные, но ещё не сверенные резервы могут отображаться отдельно; их сверяет HR. Установленная законом норма отпуска, переносы и правила праздников здесь не определены.', 'Демо: остаток отпускных дней', null, array['остаток', 'отпускных', 'дней', 'профиль', 'посмотреть']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000006', 'Как исправить сведения в профиле', 'Официальные сведения сотрудника — имя, должность, подразделение, руководитель и кадровый остаток — нельзя произвольно менять обычным сотрудником. Для исправления обратитесь в HR. Регистрация в объединённой версии проходит по персональному приглашению HR: после подтверждения email сервер завершает привязку учётной записи к кадровому профилю с данными приглашения. Пользователь не выбирает себе роль HR или директора. Если вход выполнен, но кадровый профиль отсутствует, обратитесь к администратору проекта; повторная регистрация сама по себе не исправляет привязку.', 'Демо: кадровый профиль и привязка учётной записи', null, array['профиль', 'исправить', 'изменить', 'должность', 'регистрация', 'привязка']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000007', 'Где найти назначенное обучение', 'В Academy сотрудник открывает назначенные ему активные курсы. Наличие курса в общем каталоге само по себе не является назначением. Курс назначает HR, руководитель или директор в пределах разрешённых сервером сотрудников; можно установить срок прохождения. При назначении появляется уведомление в приложении. Jana объясняет порядок обучения, но не назначает курс и не меняет его результаты.', 'Демо: назначения Jana Academy', null, array['обучение', 'назначенный', 'назначенные', 'курс', 'курсы', 'academy']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000008', 'Как пройти курс и увидеть результат', 'Для завершения обучения изучите обязательные уроки и ответьте на все вопросы теста. Пока обучение не завершено, промежуточный прогресс не превышает 99 процентов. У курса есть свой проходной балл: завершение и 100 процентов прогресса фиксируются после успешной сдачи теста с достижением этого порога. Если балл ниже порога, курс не завершён и доступна новая попытка. Готовые правильные ответы сотруднику не выдаются. Точный порог и назначенный срок смотрите в карточке курса, их нельзя угадывать.', 'Демо: прогресс и результат обучения', null, array['курс', 'прогресс', 'тест', 'результат', 'обучение', 'завершить']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000009', 'Где читать уведомления', 'Уведомления отображаются в отдельном разделе приложения: о решениях по заявкам, назначении обучения и событиях обращения в HR. Руководителю направляются предусмотренные процессом сообщения об обучении прямых подчинённых. Уведомление можно отметить прочитанным. Каждый пользователь видит только собственные уведомления. Рассылка уведомлений о заявках и курсах по email, SMS или мессенджерам не подтверждена; письма подтверждения регистрации и восстановления пароля — отдельный механизм авторизации.', 'Демо: центр уведомлений', null, array['уведомления', 'уведомление', 'прочитать', 'прочитанным']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000010', 'Что умеет AI Jana и когда обращаться в HR', 'Jana отвечает по опубликованным и проверенным материалам базы знаний и показывает точные цитаты со ссылками на источники. При отсутствии подтверждения она должна сообщить об этом, а при неоднозначном вопросе попросить уточнение. Каждый вопрос обрабатывается отдельно, история разговора не используется. Jana не читает персональные профили, зарплаты и заявки, не принимает кадровые решения и не выполняет действия вместо пользователя. Она работает на локальной модели, без платного облачного API. Ответ со ссылкой всё равно может быть неполным или неверно выбранным по смыслу.', 'Демо: границы AI Jana', null, array['jana', 'ассистент', 'помощник', 'источники', 'hr', 'умеет']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000011', 'Как перенести отпуск в Google Calendar', 'Для окончательно одобренного отпуска со статусом approved можно скачать файл .ics в разделе календаря. В Google Calendar на компьютере откройте настройки импорта и выберите этот файл. Событие включает первый и последний дни отпуска. Скачивание файла не добавляет событие автоматически и не создаёт синхронизацию с Google. Повторный импорт может создать дубликат; изменения или удаление импортированного события выполняйте вручную. На этапе pending_hr файл ещё недоступен. Экспорт курса в календарь этим способом не реализован.', 'Демо: экспорт отпуска в календарь', null, array['календарь', 'google', 'ics', 'отпуск', 'импорт']::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000012', 'Обращение в HR', 'Если ответа Jana недостаточно, можно явно отправить обращение через кнопку передачи вопроса в HR. Перед отправкой пользователь подтверждает согласие и состав передаваемого текста. Сам совет Jana обратиться в HR не создаёт заявку автоматически. Сотрудник видит свои обращения; HR отвечает в рабочем разделе, а сотрудник получает уведомление. Срок ответа и конкретный контакт HR в этой базе не установлены.', 'Демо: обращение в hr', null, array[]::text[], true, 'team-1', 'published'),
('20000000-0000-4000-8000-000000000013', 'Публикация знаний', 'HR редактирует базу знаний через рабочий раздел. Черновик не становится источником ответа до публикации и подтверждения актуальности. Просроченные или снятые с публикации статьи не используются Jana. При изменении источника старая ссылка на версию требует задать вопрос заново. Эти материалы описывают демонстрационный прототип и не являются утверждёнными кадровыми правилами Jana Post.', 'Демо: публикация знаний', null, array[]::text[], true, 'team-1', 'published')
